from collections import Counter
class Solution:
    def minGroups(self, balls):
        freqs = list(Counter(balls).values())
        best = float('inf')
        for k in range(1, max(freqs) + 1):
            total = 0
            ok = True
            for c in freqs:
                found = False
                for a in range(min(c // k, k) + 1):
                    rem = c - a * k
                    if rem % (k + 1) == 0:
                        total += a + rem // (k + 1)
                        found = True
                        break
                if not found:
                    ok = False
                    break
            if ok:
                best = min(best, total)
        return best

