public:
    int minGroups(vector<int>& balls) {
        unordered_map<int,int> cnt;
        for (int x : balls) cnt[x]++;
        vector<int> freqs;
        int mx = 0;
        for (auto& [_, c] : cnt) { freqs.push_back(c); mx = max(mx, c); }
        int best = INT_MAX;
        for (int k = 1; k <= mx; k++) {
            long long total = 0;
            bool ok = true;
            for (int c : freqs) {
                bool found = false;
                for (int a = 0; a <= min(c / k, k); a++) {
                    int rem = c - a * k;
                    if (rem % (k + 1) == 0) {
                        total += a + rem / (k + 1);
                        found = true;
                        break;
                    }
                }
                if (!found) { ok = false; break; }
            }
            if (ok) best = min(best, (int)total);
        }
        return best;
    }
};

