                    if (rem % (k + 1) == 0) {
                        total += a + rem / (k + 1);
                        found = true;
                        break;
                    }
                }
                if (!found || total >= best) { ok = found && total < best; if (!ok) break; }
            }
            if (ok) best = min(best, (int)total);
